-- PostgreSQL Phase 1 schema foundation. Apply to a new database after review.
BEGIN;
CREATE TABLE tenants (id uuid PRIMARY KEY, name varchar(120) NOT NULL, slug varchar(60) NOT NULL UNIQUE, institution_type varchar(20) NOT NULL CHECK(institution_type IN ('school','college','school_college')), status varchar(20) NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','archived')), timezone varchar(64) NOT NULL DEFAULT 'Asia/Karachi', default_locale varchar(10) NOT NULL DEFAULT 'en', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE campuses (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, name varchar(120) NOT NULL, code varchar(30), address text, city varchar(80), province varchar(80), is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,code), UNIQUE(tenant_id,id));
CREATE INDEX campuses_tenant_active_idx ON campuses(tenant_id,is_active);
CREATE TABLE users (id uuid PRIMARY KEY, name varchar(120) NOT NULL, email varchar(254) NOT NULL UNIQUE, password_hash text NOT NULL, status varchar(20) NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled','locked')), mfa_enabled boolean NOT NULL DEFAULT false, last_login_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tenant_memberships (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT, status varchar(20) NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','ended')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,user_id), UNIQUE(tenant_id,id));
CREATE INDEX memberships_user_status_idx ON tenant_memberships(user_id,status);
CREATE TABLE roles (id uuid PRIMARY KEY, tenant_id uuid REFERENCES tenants(id) ON DELETE CASCADE, code varchar(60) NOT NULL, name varchar(100) NOT NULL, is_system boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,code));
CREATE TABLE permissions (id uuid PRIMARY KEY, code varchar(100) NOT NULL UNIQUE, description text NOT NULL);
CREATE TABLE role_permissions (role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE, permission_id uuid NOT NULL REFERENCES permissions(id) ON DELETE CASCADE, PRIMARY KEY(role_id,permission_id));
CREATE TABLE user_role_assignments (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, membership_id uuid NOT NULL, role_id uuid NOT NULL REFERENCES roles(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,membership_id) REFERENCES tenant_memberships(tenant_id,id) ON DELETE CASCADE, UNIQUE(membership_id,role_id));
CREATE TABLE plans (id uuid PRIMARY KEY, code varchar(40) NOT NULL UNIQUE, name varchar(80) NOT NULL, price_pkr numeric(12,2) NOT NULL DEFAULT 0 CHECK(price_pkr>=0), billing_interval varchar(20) NOT NULL CHECK(billing_interval IN ('monthly','yearly')), limits jsonb NOT NULL DEFAULT '{}'::jsonb, features jsonb NOT NULL DEFAULT '{}'::jsonb, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE subscriptions (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, plan_id uuid NOT NULL REFERENCES plans(id) ON DELETE RESTRICT, status varchar(20) NOT NULL CHECK(status IN ('trial','active','past_due','grace_period','suspended','cancelled','expired')), starts_at timestamptz NOT NULL, ends_at timestamptz, grace_ends_at timestamptz, provider varchar(50), provider_subscription_ref varchar(160), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX subscriptions_tenant_status_idx ON subscriptions(tenant_id,status);
CREATE TABLE tenant_settings (tenant_id uuid PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE, settings jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY, tenant_id uuid REFERENCES tenants(id) ON DELETE SET NULL, actor_user_id uuid REFERENCES users(id) ON DELETE SET NULL, action varchar(120) NOT NULL, entity_type varchar(80) NOT NULL, entity_id varchar(120), request_id varchar(120), ip_hash varchar(128), details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_tenant_created_idx ON audit_logs(tenant_id,created_at DESC); CREATE INDEX audit_actor_created_idx ON audit_logs(actor_user_id,created_at DESC); CREATE INDEX audit_action_created_idx ON audit_logs(action,created_at DESC);
-- Enable RLS policies only when the application sets app.tenant_id transaction-locally from verified auth context.
ALTER TABLE campuses ENABLE ROW LEVEL SECURITY;
CREATE POLICY campuses_tenant_isolation ON campuses USING(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE tenant_memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY memberships_tenant_isolation ON tenant_memberships USING(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid);
ALTER TABLE subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY subscriptions_tenant_isolation ON subscriptions USING(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid);
COMMIT;
